import{_ as n,c as s,o as a,a as p}from"./app-olgpHTCG.js";const t="/images/rewrite/pattern-singleton/getinstance-flow.webp",e="/images/rewrite/pattern-singleton/vuex-install-guard.webp",o="/images/rewrite/pattern-singleton/modal-lifecycle.webp",c={},l=p('<h1 id="单例模式-singleton" tabindex="-1"><a class="header-anchor" href="#单例模式-singleton"><span>单例模式（Singleton）</span></a></h1><h2 id="核心要点" tabindex="-1"><a class="header-anchor" href="#核心要点"><span>核心要点</span></a></h2><ul><li><strong>定义</strong>：一个类在整个程序里只允许存在一个实例，并且对外提供一个统一的入口来拿到它。</li><li><strong>关键能力</strong>：类（或者它的工厂函数）要能&quot;记住&quot;自己是否已经造过对象。第一次调用时创建并缓存，之后每次调用都直接把缓存的那一个交出去，调用多少次、谁来调用，拿到的都是同一个引用。</li><li><strong>两种经典写法</strong>： <ul><li>静态方法 <code>getInstance</code>，把实例存在类的静态属性上；</li><li>闭包（IIFE）里放一个自由变量充当&quot;私有的缓存&quot;，返回一个负责判断的函数。</li><li>现代 JS 还可以用 <code>static #instance</code> 私有字段、在构造函数里拦截 <code>new</code>，或者干脆利用 ES Module 只执行一次的特性。</li></ul></li><li><strong>前端里的典型应用</strong>：Vuex / Redux 的全局 Store、插件的 <code>install</code> 防重复安装、全局弹框、全局的请求实例 / 日志器 / 配置对象。</li><li><strong>Vuex 的做法</strong>：<code>install</code> 里用一个模块级变量记住已经装过的 <code>Vue</code>，同一个 <code>Vue</code> 再装一次就直接 <code>return</code>（开发环境顺便报错提示），保证一个应用只有一套 Store 注入逻辑。这道判断是 <code>Vue.use</code> 自带去重之外的第二层保险；两层都失效时，重复安装会让全局混入叠加、注入逻辑重复执行（常被简化成&quot;Store 重新初始化、状态归零&quot;的说法）。</li><li><strong>两道常考题</strong>：基于 <code>localStorage</code> 封装一个单例 <code>Storage</code>（静态方法版 + 闭包版都要会写）；实现一个全局唯一的 Modal 弹框（按需创建、反复复用同一个 DOM 节点）。</li><li><strong>要注意的坑</strong>：实例别挂在 <code>this</code> 上（那样每个对象各存一份，不是单例）；单例是全局可变状态，会给单元测试和 SSR 带来麻烦。</li></ul><h2 id="单例到底解决什么问题" tabindex="-1"><a class="header-anchor" href="#单例到底解决什么问题"><span>单例到底解决什么问题</span></a></h2><p>有些对象天然&quot;只该有一个&quot;：</p><table><thead><tr><th>场景</th><th>如果出现多份会怎样</th></tr></thead><tbody><tr><td>全局状态仓库（Store）</td><td>组件 A 改了自己那份，组件 B 读的是另一份，数据对不上</td></tr><tr><td>本地存储的封装</td><td>每处 <code>new</code> 一个包装对象，浪费内存，配置（前缀、过期策略）也可能不一致</td></tr><tr><td>全局弹框 / 遮罩</td><td>每点一次按钮就往 <code>body</code> 里塞一个新节点，页面上叠了一堆</td></tr><tr><td>日志器、埋点 SDK、WebSocket 连接</td><td>重复连接、重复上报</td></tr></tbody></table><p>单例模式给出的方案很朴素：<strong>创建对象这件事交给一个入口统一把关</strong>。入口先检查&quot;之前有没有造过&quot;，没有才 <code>new</code>，有就把旧的返回。</p><p><img src="'+t+`" alt="单例入口的判断流程：首次调用创建并缓存实例，之后的调用全部拿到同一个缓存对象"></p><h2 id="实现方式" tabindex="-1"><a class="header-anchor" href="#实现方式"><span>实现方式</span></a></h2><h3 id="一个常见的错误写法" tabindex="-1"><a class="header-anchor" href="#一个常见的错误写法"><span>一个常见的错误写法</span></a></h3><p>先看一个看起来像单例、其实不是的版本：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">class</span> <span class="token class-name">Printer</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token parameter">model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>model <span class="token operator">=</span> model<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>cache <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span>          <span class="token comment">// 缓存放在了&quot;实例&quot;上</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token function">acquire</span><span class="token punctuation">(</span><span class="token parameter">model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span>cache<span class="token punctuation">)</span> <span class="token keyword">this</span><span class="token punctuation">.</span>cache <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Printer</span><span class="token punctuation">(</span>model<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>cache<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> p1 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Printer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">acquire</span><span class="token punctuation">(</span><span class="token string">&#39;HP&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> p2 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Printer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">acquire</span><span class="token punctuation">(</span><span class="token string">&#39;Canon&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>p1 <span class="token operator">===</span> p2<span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// false</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>问题出在 <code>this.cache</code>：它属于某一个具体对象，每 <code>new Printer()</code> 一次就多一份独立的缓存。只有恰好一直复用同一个 <code>Printer</code> 对象去调 <code>acquire</code> 时才&quot;像&quot;单例。而且外面还得先 <code>new</code> 一个对象才能拿单例，这本身就和&quot;只要一个实例&quot;矛盾。</p><p><strong>正确的做法是把缓存放在所有调用方共享的位置</strong>：类本身（静态属性）或者闭包里。</p><h3 id="写法一-静态方法" tabindex="-1"><a class="header-anchor" href="#写法一-静态方法"><span>写法一：静态方法</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">class</span> <span class="token class-name">AppConfig</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">static</span> <span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 没造过就造一个，造过就直接用</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>AppConfig<span class="token punctuation">.</span>instance<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      AppConfig<span class="token punctuation">.</span>instance <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">AppConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> AppConfig<span class="token punctuation">.</span>instance<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">describe</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">theme=</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token keyword">this</span><span class="token punctuation">.</span>theme <span class="token operator">??</span> <span class="token string">&#39;light&#39;</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> c1 <span class="token operator">=</span> AppConfig<span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> c2 <span class="token operator">=</span> AppConfig<span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">c1<span class="token punctuation">.</span>theme <span class="token operator">=</span> <span class="token string">&#39;dark&#39;</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>c2<span class="token punctuation">.</span><span class="token function">describe</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// theme=dark，改的是同一个对象</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>c1 <span class="token operator">===</span> c2<span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>static</code> 方法挂在类上，不需要先创建对象就能调用；<code>AppConfig.instance</code> 也是类级别的属性，所有调用方共享。不管调用多少次 <code>getInstance</code>，经过这层判断拦截后，<code>c1</code>、<code>c2</code> 指向的都是那唯一一个对象。</p><p>判断逻辑写在静态方法里还是写进构造函数里都可以，后面会给出构造函数的版本。</p><h3 id="写法二-闭包" tabindex="-1"><a class="header-anchor" href="#写法二-闭包"><span>写法二：闭包</span></a></h3><p>把缓存藏进立即执行函数的作用域，外部根本访问不到，相当于一个私有变量：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line">AppConfig<span class="token punctuation">.</span>getInstance <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> shared<span class="token punctuation">;</span>                   <span class="token comment">// 自由变量，只有下面这个函数能读写</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>shared <span class="token operator">===</span> <span class="token keyword">undefined</span><span class="token punctuation">)</span> shared <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">AppConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> shared<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>AppConfig<span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> AppConfig<span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>和静态属性版相比，闭包版的好处是缓存不会被外部直接改掉（静态属性版里任何人都可以写 <code>AppConfig.instance = null</code> 把它重置）。</p><h3 id="写法三-现代-js-的写法" tabindex="-1"><a class="header-anchor" href="#写法三-现代-js-的写法"><span>写法三：现代 JS 的写法</span></a></h3><p>ES2022 起类支持私有字段，可以把缓存藏在 <code>static #</code> 里，并且在构造函数里拦截，让直接 <code>new</code> 也拿到同一个对象：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">class</span> <span class="token class-name">Logger</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">static</span> #only <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">  #lines <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 已经有实例了：返回它，替换掉这次 new 出来的新对象</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>Logger<span class="token punctuation">.</span>#only<span class="token punctuation">)</span> <span class="token keyword">return</span> Logger<span class="token punctuation">.</span>#only<span class="token punctuation">;</span></span>
<span class="line">    Logger<span class="token punctuation">.</span>#only <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">static</span> <span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> Logger<span class="token punctuation">.</span>#only <span class="token operator">??</span> <span class="token keyword">new</span> <span class="token class-name">Logger</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">log</span><span class="token punctuation">(</span><span class="token parameter">msg</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>#lines<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>#lines<span class="token punctuation">.</span>length<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> l1 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Logger</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> l2 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Logger</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">l1<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;boot&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>l1 <span class="token operator">===</span> l2<span class="token punctuation">)</span><span class="token punctuation">;</span>                       <span class="token comment">// true</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>l2<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;ready&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                 <span class="token comment">// 2，两条日志记在同一个对象里</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>Logger<span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> l1<span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里用到一条语言规则：<strong>构造函数如果显式 <code>return</code> 一个对象，<code>new</code> 表达式的结果就是这个对象</strong>，而不是新建的 <code>this</code>。后面闭包版 <code>Storage</code> 能用 <code>new</code> 调用，也是同一个原理。</p><p>另外，在模块化的工程里，最省事的单例其实是 <strong>ES Module 本身</strong>：模块只会被求值一次，所有 <code>import</code> 拿到的是同一个导出对象。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// request.js</span></span>
<span class="line"><span class="token keyword">import</span> axios <span class="token keyword">from</span> <span class="token string">&#39;axios&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> http <span class="token operator">=</span> axios<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">baseURL</span><span class="token operator">:</span> <span class="token string">&#39;/api&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">timeout</span><span class="token operator">:</span> <span class="token number">8000</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 任何文件 import { http } from &#39;./request&#39; 拿到的都是同一个实例</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="饿汉和懒汉" tabindex="-1"><a class="header-anchor" href="#饿汉和懒汉"><span>饿汉和懒汉</span></a></h3><table><thead><tr><th></th><th>懒汉式（lazy）</th><th>饿汉式（eager）</th></tr></thead><tbody><tr><td>创建时机</td><td>第一次调用 <code>getInstance</code> 时才创建</td><td>类 / 模块加载时立刻创建</td></tr><tr><td>优点</td><td>用不到就不占资源</td><td>写法最简单，没有判断分支</td></tr><tr><td>例子</td><td>上面的 <code>getInstance</code>、后面的弹框</td><td>模块顶层直接 <code>export const store = createStore()</code></td></tr></tbody></table><p>JS 是单线程的，懒汉式不需要像 Java 那样考虑多线程下的&quot;双重检查加锁&quot;。不过如果创建过程是异步的（比如要先 <code>await</code> 建立连接），要缓存的是 <strong>Promise</strong> 而不是结果，否则两个几乎同时的调用会各自发起一次创建。</p><h2 id="生产实践-vuex-的-store-为什么只有一个" tabindex="-1"><a class="header-anchor" href="#生产实践-vuex-的-store-为什么只有一个"><span>生产实践：Vuex 的 Store 为什么只有一个</span></a></h2><p><code>Redux</code> 和 <code>Vuex</code> 都把整个应用的状态集中放进一个全局 <code>Store</code>，这个 <code>Store</code> 就是单例思想在前端最典型的落地。</p><h3 id="store-为什么要唯一" tabindex="-1"><a class="header-anchor" href="#store-为什么要唯一"><span>Store 为什么要唯一</span></a></h3><p>Vuex 官方文档对这点的解释是：Vuex 采用<strong>单一状态树</strong>，一个对象装下应用的全部层级状态，作为&quot;唯一数据源（SSOT, Single Source of Truth）&quot;存在，所以每个应用只包含一个 store 实例。好处是任何一块状态都能直接定位到，调试时也能一次性拿到整个应用当前状态的快照。</p><p>为什么需要这样一个集中的地方？组件少的时候，父子之间用 props 和事件传数据就够了。可一旦组件很多、关系交错、嵌套又深，层层传递会让逻辑越来越难维护。更好的办法是把多个组件共享的数据抽出来放到全局，让组件按照约定好的规则去读写，状态的变化就变得可预测。Vuex 就是干这件事的，而那个存放共享数据的唯一数据源，就是 Store。</p><h3 id="vuex-怎么保证-store-唯一" tabindex="-1"><a class="header-anchor" href="#vuex-怎么保证-store-唯一"><span>Vuex 怎么保证 Store 唯一</span></a></h3><p>在 Vue 2 项目里接入 Vuex 一般是这样：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">import</span> Vue <span class="token keyword">from</span> <span class="token string">&#39;vue&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">import</span> Vuex <span class="token keyword">from</span> <span class="token string">&#39;vuex&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">Vue<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span>Vuex<span class="token punctuation">)</span><span class="token punctuation">;</span>                         <span class="token comment">// 安装插件</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> store <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Vuex<span class="token punctuation">.</span>Store</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">state</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">count</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">new</span> <span class="token class-name">Vue</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">el</span><span class="token operator">:</span> <span class="token string">&#39;#app&#39;</span><span class="token punctuation">,</span></span>
<span class="line">  store<span class="token punctuation">,</span>                               <span class="token comment">// 注入根实例，子组件通过 this.$store 访问</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>Vue.use()</code> 会调用插件对象上的 <code>install</code> 方法。Vuex 的 <code>install</code> 负责把 Store 的注入逻辑挂到 Vue 上（通过全局混入，在每个组件的 <code>beforeCreate</code> 里设置 <code>this.$store</code>）。换句话说，<strong>每执行一次 <code>install</code>，就会尝试再给 Vue 注入一次 Store</strong>。</p><p>Vuex 3 源码里的 <code>install</code> 长这样（节选，注释是我们加的）：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">let</span> Vue <span class="token comment">// 模块级变量：记住已经装过 Vuex 的那个 Vue 构造函数</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">install</span> <span class="token punctuation">(</span><span class="token parameter">_Vue</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 同一个 Vue 已经装过了：开发环境报错提示，然后直接退出</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>Vue <span class="token operator">&amp;&amp;</span> _Vue <span class="token operator">===</span> Vue<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>__DEV__<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      console<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token string">&#39;[vuex] already installed. Vue.use(Vuex) should be called only once.&#39;</span></span>
<span class="line">      <span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token comment">// 第一次安装：记下来，再把初始化逻辑混入 Vue 的生命周期钩子</span></span>
<span class="line">  Vue <span class="token operator">=</span> _Vue</span>
<span class="line">  <span class="token function">applyMixin</span><span class="token punctuation">(</span>Vue<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>模块顶部的 <code>let Vue</code> 扮演的正是前面 <code>getInstance</code> 里 <code>instance</code> 的角色：第一次进来时记下，之后同一个 <code>Vue</code> 再来就被拦在门外。于是一个 Vue 应用只会被装一次 Vuex，也就只有一个全局 Store。</p><blockquote><p>补充两点：</p><ol><li>Vue 自己的 <code>Vue.use</code> 也会记录装过的插件（<code>installedPlugins</code>），重复 <code>use</code> 同一个插件在 Vue 这一层就被挡掉了；Vuex 内部的这道判断是一层额外保险，针对的是绕过 <code>Vue.use</code>、直接调用 <code>install</code> 的情况。</li><li>到了 Vue 3 + Vuex 4 / Pinia，写法变成 <code>app.use(createStore(...))</code> / <code>app.use(createPinia())</code>，Store 挂在具体的 <code>app</code> 实例上（<code>app.config.globalProperties</code> 和 <code>provide</code>），&quot;每个应用一个 Store&quot;依旧成立，只是作用域从全局 <code>Vue</code> 收窄到了单个 <code>app</code>。</li></ol></blockquote><h3 id="如果-install-不做单例判断会怎样" tabindex="-1"><a class="header-anchor" href="#如果-install-不做单例判断会怎样"><span>如果 install 不做单例判断会怎样</span></a></h3><p>先把前提说清楚：前面提到 <code>Vue.use</code> 自己就会去重，所以下面讨论的是<strong>两层保护都不起作用</strong>的情形——要么 Vue 层没有 <code>installedPlugins</code> 去重，要么代码绕过 <code>Vue.use</code>、直接调用了 <code>Vuex.install</code>。在这个前提下，假设 Vuex 也去掉了自己的判断，而项目里又一不小心装了两次：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// main.js</span></span>
<span class="line">Vuex<span class="token punctuation">.</span><span class="token function">install</span><span class="token punctuation">(</span>Vue<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 首次安装</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ……业务代码往 store 里写了登录信息、购物车等数据……</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 某个后来加的模块绕过 Vue.use，又手动调了一次</span></span>
<span class="line">Vuex<span class="token punctuation">.</span><span class="token function">install</span><span class="token punctuation">(</span>Vue<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这时第二次调用会把 <code>applyMixin(Vue)</code> 再执行一遍，<strong>真实的直接后果是全局混入被叠加</strong>：每个组件创建时，<code>beforeCreate</code> 里的注入逻辑（Vuex 3 里叫 <code>vuexInit</code>）会跑两遍、三遍……装几次就跑几次。</p><p>有人会问：Vue 2.6 起合并生命周期钩子时会做去重（<code>dedupeHooks</code>），重复混入不是会被合并掉吗？这个去重按函数引用比较，只能挡住&quot;同一个函数对象被混入多次&quot;。而 Vuex 3 的 <code>vuexInit</code> 是写在 <code>applyMixin</code> 函数体内部的函数声明，每调用一次 <code>applyMixin</code> 就生成一个新的函数对象，引用各不相同，去重认不出它们是&quot;同一个钩子&quot;。我们用 vue@2.6.14 + vuex@3.6.2 实测过：把 Vuex 自带的 <code>applyMixin</code> 连调两次，<code>Vue.options.beforeCreate</code> 里有 2 个钩子，创建一个组件时 <code>vuexInit</code> 执行 2 次，和 vue@2.5.17 下的结果一样。反过来，如果插件把钩子函数定义在模块顶层、每次混入的是同一个引用，在 2.6+ 里就会被去重，这时重复安装真正的隐患就只剩 <code>install</code> 里那些和钩子无关、只该做一次的副作用（注册全局组件、挂原型属性、发起初始化请求等）。</p><p>注意 Store 本身是用户代码 <code>new Vuex.Store(...)</code> 创建的，<code>vuexInit</code> 每次注入的都是同一个 <code>options.store</code>，所以 Vuex 3 里重复 <code>install</code> 并不会把已有状态清空，它带来的是重复执行、性能浪费，以及插件初始化逻辑里任何&quot;只该跑一次&quot;的副作用被放大。</p><p>常见的另一种说法是&quot;重复安装会让 Store 重新初始化、之前写入的数据全部归零&quot;。把它当成一种简化的、最坏情况下的概括来理解就行：如果某个插件的 <code>install</code> 里会自己创建全局状态容器，没有单例判断时第二次安装确实会造出一个新容器、把旧数据顶掉。无论具体表现是混入叠加还是状态被覆盖，&quot;全局初始化只能执行一次&quot;这个要求是一样的，这正是单例判断存在的意义。下面这张图把有守卫和没守卫两种情况放在一起对比：</p><p><img src="`+e+`" alt="绕过 Vue.use 直接再调一次 install：有单例守卫时第二次直接返回；没有守卫时全局混入被叠加、注入逻辑重复执行"></p><p>用一段可运行的小代码模拟这道守卫的效果：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">let</span> installedOn <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> initCount <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">install</span><span class="token punctuation">(</span><span class="token parameter">App</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>installedOn <span class="token operator">&amp;&amp;</span> installedOn <span class="token operator">===</span> App<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">warn</span><span class="token punctuation">(</span><span class="token string">&#39;[myplugin] 已经安装过，忽略本次 use()&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  installedOn <span class="token operator">=</span> App<span class="token punctuation">;</span></span>
<span class="line">  initCount<span class="token operator">++</span><span class="token punctuation">;</span>            <span class="token comment">// 真正的初始化只会走到这里一次</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">FakeVue</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token function">install</span><span class="token punctuation">(</span>FakeVue<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">install</span><span class="token punctuation">(</span>FakeVue<span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// 打出警告，直接返回</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>initCount<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 1</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>所以 <code>install</code> 里的单例判断不是可有可无的。同样的思路在 <code>Redux</code>（<code>createStore</code> 产出的全局 store）、<code>jQuery</code>（全局只暴露一个 <code>$</code> / <code>jQuery</code> 对象）等很多前端库里都能看到。</p><h2 id="面试题一-实现一个单例的-storage" tabindex="-1"><a class="header-anchor" href="#面试题一-实现一个单例的-storage"><span>面试题一：实现一个单例的 Storage</span></a></h2><p><strong>题目</strong>：基于 <code>localStorage</code> 封装一个 <code>Storage</code>，要求它是单例，并提供 <code>setItem(key, value)</code> 和 <code>getItem(key)</code> 两个方法。</p><p><strong>思路</strong>：判断逻辑放在静态方法里或者构造函数里都可以；面试时最好静态方法版和闭包版各写一份，展示两种思路都掌握了。</p><h3 id="静态方法版" tabindex="-1"><a class="header-anchor" href="#静态方法版"><span>静态方法版</span></a></h3><p>顺手做一点增强：存取时用 JSON 序列化，这样对象也能直接存。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">class</span> <span class="token class-name">Storage</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">static</span> <span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// ??= ：左边是 null/undefined 时才赋值</span></span>
<span class="line">    Storage<span class="token punctuation">.</span>instance <span class="token operator">??=</span> <span class="token keyword">new</span> <span class="token class-name">Storage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> Storage<span class="token punctuation">.</span>instance<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">setItem</span><span class="token punctuation">(</span><span class="token parameter">key<span class="token punctuation">,</span> value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    localStorage<span class="token punctuation">.</span><span class="token function">setItem</span><span class="token punctuation">(</span>key<span class="token punctuation">,</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">getItem</span><span class="token punctuation">(</span><span class="token parameter">key</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> raw <span class="token operator">=</span> localStorage<span class="token punctuation">.</span><span class="token function">getItem</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> raw <span class="token operator">===</span> <span class="token keyword">null</span> <span class="token operator">?</span> <span class="token keyword">null</span> <span class="token operator">:</span> <span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">parse</span><span class="token punctuation">(</span>raw<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> cartA <span class="token operator">=</span> Storage<span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> cartB <span class="token operator">=</span> Storage<span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">cartA<span class="token punctuation">.</span><span class="token function">setItem</span><span class="token punctuation">(</span><span class="token string">&#39;cart&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">sku</span><span class="token operator">:</span> <span class="token string">&#39;A-1024&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">qty</span><span class="token operator">:</span> <span class="token number">3</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>cartB<span class="token punctuation">.</span><span class="token function">getItem</span><span class="token punctuation">(</span><span class="token string">&#39;cart&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// { sku: &#39;A-1024&#39;, qty: 3 }</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>cartA <span class="token operator">===</span> cartB<span class="token punctuation">)</span><span class="token punctuation">;</span>         <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：浏览器全局本来就有一个叫 <code>Storage</code> 的接口（<code>localStorage</code> 就是它的实例），在全局作用域用 <code>class Storage</code> 会遮蔽它。题目要求叫这个名字没问题，真实项目里建议写在模块里或者换个名字（比如 <code>LocalCache</code>）。</p><h3 id="闭包版" tabindex="-1"><a class="header-anchor" href="#闭包版"><span>闭包版</span></a></h3><p>用 ES5 的写法，把读写方法放在一个基础构造函数的原型上，再用闭包控制&quot;只 new 一次&quot;：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// 真正干活的对象：方法挂在原型上</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">StorageCore</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token class-name">StorageCore</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function-variable function">setItem</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">key<span class="token punctuation">,</span> value</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  localStorage<span class="token punctuation">.</span><span class="token function">setItem</span><span class="token punctuation">(</span>key<span class="token punctuation">,</span> value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">StorageCore</span><span class="token punctuation">.</span>prototype<span class="token punctuation">.</span><span class="token function-variable function">getItem</span> <span class="token operator">=</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">key</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> localStorage<span class="token punctuation">.</span><span class="token function">getItem</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 对外暴露的入口：闭包里缓存唯一的 StorageCore 实例</span></span>
<span class="line"><span class="token keyword">var</span> Storage <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">var</span> cached <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>cached <span class="token operator">===</span> <span class="token keyword">null</span><span class="token punctuation">)</span> cached <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">StorageCore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> cached<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">var</span> s1 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Storage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 用 new 调用</span></span>
<span class="line"><span class="token keyword">var</span> s2 <span class="token operator">=</span> <span class="token function">Storage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>       <span class="token comment">// 直接调用，效果一样</span></span>
<span class="line">s1<span class="token punctuation">.</span><span class="token function">setItem</span><span class="token punctuation">(</span><span class="token string">&#39;lang&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;zh-CN&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>s2<span class="token punctuation">.</span><span class="token function">getItem</span><span class="token punctuation">(</span><span class="token string">&#39;lang&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// zh-CN</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>s1 <span class="token operator">===</span> s2<span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// true</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>为什么 <code>new Storage()</code> 和 <code>Storage()</code> 结果一样？因为这个函数显式 <code>return</code> 了一个对象，<code>new</code> 时新建的 <code>this</code> 会被丢弃，表达式的值就是返回的 <code>cached</code>。所以加不加 <code>new</code> 都拿到同一个实例。</p><p>（以上两段在 Node 里用一个 <code>Map</code> 模拟 <code>localStorage</code> 跑过，输出与注释一致。）</p><h2 id="面试题二-实现一个全局唯一的-modal-弹框" tabindex="-1"><a class="header-anchor" href="#面试题二-实现一个全局唯一的-modal-弹框"><span>面试题二：实现一个全局唯一的 Modal 弹框</span></a></h2><p>这几乎是讲单例时必举的例子，也是单例模式在前端早期最集中的应用场景：页面上无论点多少次&quot;打开&quot;，弹框节点都只应该创建一个。</p><p><strong>思路</strong>：套路和前面完全一样。记住三样东西：一个缓存变量（<code>instance</code>）、一个负责判断的入口（<code>getInstance</code> 或闭包返回的函数）、静态方法或闭包二选一。另外要做到<strong>懒创建</strong>：没点过&quot;打开&quot;就不创建节点，避免白占内存。</p><p><img src="`+o+`" alt="全局弹框的生命周期：第一次打开时创建节点，关闭只是隐藏，之后再打开复用同一个节点"></p><h3 id="闭包版-1" tabindex="-1"><a class="header-anchor" href="#闭包版-1"><span>闭包版</span></a></h3><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token doctype"><span class="token punctuation">&lt;!</span><span class="token doctype-tag">DOCTYPE</span> <span class="token name">html</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span> <span class="token attr-name">lang</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>zh-CN<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">charset</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>UTF-8<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span>全局唯一弹框<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>style</span><span class="token punctuation">&gt;</span></span><span class="token style"><span class="token language-css"></span>
<span class="line">    <span class="token selector">.login-dialog</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">position</span><span class="token punctuation">:</span> fixed<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">inset</span><span class="token punctuation">:</span> 50% auto auto 50%<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">transform</span><span class="token punctuation">:</span> <span class="token function">translate</span><span class="token punctuation">(</span>-50%<span class="token punctuation">,</span> -50%<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">width</span><span class="token punctuation">:</span> 260px<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">padding</span><span class="token punctuation">:</span> 32px 0<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">text-align</span><span class="token punctuation">:</span> center<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">background</span><span class="token punctuation">:</span> #fff<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">border</span><span class="token punctuation">:</span> 1px solid #333<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">border-radius</span><span class="token punctuation">:</span> 8px<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>style</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>show<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>登录<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>hide<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>取消<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"></span>
<span class="line">    <span class="token comment">// 闭包里缓存唯一的弹框节点</span></span>
<span class="line">    <span class="token keyword">const</span> getDialog <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">let</span> dialog <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">      <span class="token keyword">return</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>dialog<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">          dialog <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">createElement</span><span class="token punctuation">(</span><span class="token string">&#39;div&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">          dialog<span class="token punctuation">.</span>className <span class="token operator">=</span> <span class="token string">&#39;login-dialog&#39;</span><span class="token punctuation">;</span></span>
<span class="line">          dialog<span class="token punctuation">.</span>textContent <span class="token operator">=</span> <span class="token string">&#39;请先登录（这个弹框全局只有一个）&#39;</span><span class="token punctuation">;</span></span>
<span class="line">          dialog<span class="token punctuation">.</span>hidden <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">          document<span class="token punctuation">.</span>body<span class="token punctuation">.</span><span class="token function">appendChild</span><span class="token punctuation">(</span>dialog<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">return</span> dialog<span class="token punctuation">;</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;show&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;click&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token function">getDialog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>hidden <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span>     <span class="token comment">// 第一次点击时才真正创建节点</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;hide&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;click&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token function">getDialog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>hidden <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>      <span class="token comment">// 关闭只是隐藏，节点保留以便复用</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>和 <code>Storage</code> 一样，这里的 <code>getDialog</code> 也可以写成 <code>new getDialog()</code>，结果相同，因为函数返回的是一个对象（DOM 节点）。</p><blockquote><p>一个小细节：如果用户还没点过&quot;登录&quot;就先点了&quot;取消&quot;，上面的写法会为了隐藏而创建节点。想彻底懒加载，可以单独暴露一个&quot;只查不建&quot;的方法，或者在关闭时先判断节点是否存在。</p></blockquote><h3 id="es6-class-版" tabindex="-1"><a class="header-anchor" href="#es6-class-版"><span>ES6 class 版</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">class</span> <span class="token class-name">LoginDialog</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">static</span> #el <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">static</span> <span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>LoginDialog<span class="token punctuation">.</span>#el<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">const</span> el <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">createElement</span><span class="token punctuation">(</span><span class="token string">&#39;div&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      el<span class="token punctuation">.</span>className <span class="token operator">=</span> <span class="token string">&#39;login-dialog&#39;</span><span class="token punctuation">;</span></span>
<span class="line">      el<span class="token punctuation">.</span>textContent <span class="token operator">=</span> <span class="token string">&#39;请先登录（这个弹框全局只有一个）&#39;</span><span class="token punctuation">;</span></span>
<span class="line">      el<span class="token punctuation">.</span>hidden <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">      document<span class="token punctuation">.</span>body<span class="token punctuation">.</span><span class="token function">appendChild</span><span class="token punctuation">(</span>el<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      LoginDialog<span class="token punctuation">.</span>#el <span class="token operator">=</span> el<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> LoginDialog<span class="token punctuation">.</span>#el<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">static</span> <span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token punctuation">{</span> LoginDialog<span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>hidden <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">static</span> <span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>LoginDialog<span class="token punctuation">.</span>#el<span class="token punctuation">)</span> LoginDialog<span class="token punctuation">.</span>#el<span class="token punctuation">.</span>hidden <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;show&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;click&#39;</span><span class="token punctuation">,</span> LoginDialog<span class="token punctuation">.</span>open<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;hide&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;click&#39;</span><span class="token punctuation">,</span> LoginDialog<span class="token punctuation">.</span>close<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>close</code> 里先判断节点是否存在，顺带解决了上面提到的&quot;没打开就关闭也会创建节点&quot;的问题。</p><p>可以看到，这类题的特点就是：核心套路记牢了，换个场景几乎可以直接默写。设计模式类的题目普遍如此，抓住每种模式的那一两个关键动作，就能举一反三。</p><h2 id="单例的代价" tabindex="-1"><a class="header-anchor" href="#单例的代价"><span>单例的代价</span></a></h2><p>单例好用，但它本质上是<strong>全局可变状态</strong>，有几件事要心里有数：</p><ul><li><strong>测试难隔离</strong>：一个用例改了单例里的数据，会影响后面的用例。常见做法是给单例留一个仅测试使用的重置方法，或者通过依赖注入把实例传进去，而不是在代码里到处直接调用 <code>getInstance()</code>。</li><li><strong>SSR 的跨请求污染</strong>：服务端渲染时 Node 进程长期存活，模块级的单例会被所有用户请求共享，A 用户的数据可能泄露给 B 用户。所以 Nuxt、Pinia 等都要求在每个请求里新建 Store，而不是导出一个模块级的 Store。</li><li><strong>隐藏依赖</strong>：函数内部悄悄调用全局单例，调用方从签名上看不出它依赖了什么，重构时容易出错。</li><li><strong>多个 bundle / iframe</strong>：同一份代码被打进两个包、或者在不同 iframe 里各执行一次，就会有两个&quot;单例&quot;。需要跨边界共享时，要把实例挂到真正共享的位置（比如 <code>window</code> 上的某个命名空间）。</li></ul><h2 id="面试速答模板" tabindex="-1"><a class="header-anchor" href="#面试速答模板"><span>面试速答模板</span></a></h2><blockquote><p>单例模式是说一个类只能有一个实例，并且提供一个全局访问点。实现的关键是让创建入口记住自己有没有创建过：第一次调用时 <code>new</code> 一个并缓存起来，以后直接返回缓存。JS 里常见两种写法：一种是静态方法 <code>getInstance</code>，实例存在类的静态属性上；另一种是用闭包里的自由变量做缓存，外部改不到，更安全。现代写法还可以用 <code>static #instance</code> 私有字段，或者在构造函数里判断后 <code>return</code> 已有实例，让直接 <code>new</code> 也拿到同一个对象；工程里 ES Module 只执行一次，导出一个对象本身就是单例。前端最典型的应用是 Vuex / Redux 的全局 Store，Vuex 的 <code>install</code> 用一个模块级变量记住装过的 Vue，重复安装就直接返回，保证一个应用只有一套 Store 注入逻辑；它和 <code>Vue.use</code> 自带的去重是两层保护，如果绕过 <code>Vue.use</code> 直接重复调用 <code>install</code>，没有这道判断就会让全局混入叠加、每个组件的注入逻辑重复执行。常见面试题是封装单例的 <code>localStorage</code> 工具和全局唯一的弹框，弹框要懒创建、关闭时只隐藏不销毁。最后要注意单例是全局可变状态，会给单元测试和 SSR 跨请求共享带来问题，必要时提供重置方法或按请求创建实例。</p></blockquote>`,84),i=[l];function u(r,d){return a(),s("div",null,i)}const v=n(c,[["render",u],["__file","02-2-创建型-单例模式.html.vue"]]),m=JSON.parse('{"path":"/%E5%B8%B8%E7%94%A8%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F/02-2-%E5%88%9B%E5%BB%BA%E5%9E%8B-%E5%8D%95%E4%BE%8B%E6%A8%A1%E5%BC%8F.html","title":"创建型 单例模式","lang":"zh-CN","frontmatter":{"title":"创建型 单例模式","description":"单例模式（Singleton） 核心要点 定义：一个类在整个程序里只允许存在一个实例，并且对外提供一个统一的入口来拿到它。 关键能力：类（或者它的工厂函数）要能\\"记住\\"自己是否已经造过对象。第一次调用时创建并缓存，之后每次调用都直接把缓存的那一个交出去，调用多少次、谁来调用，拿到的都是同一个引用。 两种经典写法： 静态方法 getInstance，把实...","head":[["meta",{"property":"og:url","content":"https://interview.leeguoo.com/%E5%B8%B8%E7%94%A8%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F/02-2-%E5%88%9B%E5%BB%BA%E5%9E%8B-%E5%8D%95%E4%BE%8B%E6%A8%A1%E5%BC%8F.html"}],["meta",{"property":"og:site_name","content":"前端面试题集锦"}],["meta",{"property":"og:title","content":"创建型 单例模式"}],["meta",{"property":"og:description","content":"单例模式（Singleton） 核心要点 定义：一个类在整个程序里只允许存在一个实例，并且对外提供一个统一的入口来拿到它。 关键能力：类（或者它的工厂函数）要能\\"记住\\"自己是否已经造过对象。第一次调用时创建并缓存，之后每次调用都直接把缓存的那一个交出去，调用多少次、谁来调用，拿到的都是同一个引用。 两种经典写法： 静态方法 getInstance，把实..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://interview.leeguoo.com/images/rewrite/pattern-singleton/getinstance-flow.webp"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-02T11:46:12.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-02T11:46:12.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"创建型 单例模式\\",\\"image\\":[\\"https://interview.leeguoo.com/images/rewrite/pattern-singleton/getinstance-flow.webp\\",\\"https://interview.leeguoo.com/images/rewrite/pattern-singleton/vuex-install-guard.webp\\",\\"https://interview.leeguoo.com/images/rewrite/pattern-singleton/modal-lifecycle.webp\\"],\\"dateModified\\":\\"2026-10-02T11:46:12.000Z\\",\\"author\\":[]}"]]},"headers":[{"level":2,"title":"核心要点","slug":"核心要点","link":"#核心要点","children":[]},{"level":2,"title":"单例到底解决什么问题","slug":"单例到底解决什么问题","link":"#单例到底解决什么问题","children":[]},{"level":2,"title":"实现方式","slug":"实现方式","link":"#实现方式","children":[{"level":3,"title":"一个常见的错误写法","slug":"一个常见的错误写法","link":"#一个常见的错误写法","children":[]},{"level":3,"title":"写法一：静态方法","slug":"写法一-静态方法","link":"#写法一-静态方法","children":[]},{"level":3,"title":"写法二：闭包","slug":"写法二-闭包","link":"#写法二-闭包","children":[]},{"level":3,"title":"写法三：现代 JS 的写法","slug":"写法三-现代-js-的写法","link":"#写法三-现代-js-的写法","children":[]},{"level":3,"title":"饿汉和懒汉","slug":"饿汉和懒汉","link":"#饿汉和懒汉","children":[]}]},{"level":2,"title":"生产实践：Vuex 的 Store 为什么只有一个","slug":"生产实践-vuex-的-store-为什么只有一个","link":"#生产实践-vuex-的-store-为什么只有一个","children":[{"level":3,"title":"Store 为什么要唯一","slug":"store-为什么要唯一","link":"#store-为什么要唯一","children":[]},{"level":3,"title":"Vuex 怎么保证 Store 唯一","slug":"vuex-怎么保证-store-唯一","link":"#vuex-怎么保证-store-唯一","children":[]},{"level":3,"title":"如果 install 不做单例判断会怎样","slug":"如果-install-不做单例判断会怎样","link":"#如果-install-不做单例判断会怎样","children":[]}]},{"level":2,"title":"面试题一：实现一个单例的 Storage","slug":"面试题一-实现一个单例的-storage","link":"#面试题一-实现一个单例的-storage","children":[{"level":3,"title":"静态方法版","slug":"静态方法版","link":"#静态方法版","children":[]},{"level":3,"title":"闭包版","slug":"闭包版","link":"#闭包版","children":[]}]},{"level":2,"title":"面试题二：实现一个全局唯一的 Modal 弹框","slug":"面试题二-实现一个全局唯一的-modal-弹框","link":"#面试题二-实现一个全局唯一的-modal-弹框","children":[{"level":3,"title":"闭包版","slug":"闭包版-1","link":"#闭包版-1","children":[]},{"level":3,"title":"ES6 class 版","slug":"es6-class-版","link":"#es6-class-版","children":[]}]},{"level":2,"title":"单例的代价","slug":"单例的代价","link":"#单例的代价","children":[]},{"level":2,"title":"面试速答模板","slug":"面试速答模板","link":"#面试速答模板","children":[]}],"git":{"updatedTime":1790941572000,"contributors":[{"name":"leeguooooo","email":"guoli@zhihu.com","commits":3}]},"autoDesc":true,"filePathRelative":"常用设计模式/02-2-创建型-单例模式.md","excerpt":"\\n<h2>核心要点</h2>\\n<ul>\\n<li><strong>定义</strong>：一个类在整个程序里只允许存在一个实例，并且对外提供一个统一的入口来拿到它。</li>\\n<li><strong>关键能力</strong>：类（或者它的工厂函数）要能\\"记住\\"自己是否已经造过对象。第一次调用时创建并缓存，之后每次调用都直接把缓存的那一个交出去，调用多少次、谁来调用，拿到的都是同一个引用。</li>\\n<li><strong>两种经典写法</strong>：\\n<ul>\\n<li>静态方法 <code>getInstance</code>，把实例存在类的静态属性上；</li>\\n<li>闭包（IIFE）里放一个自由变量充当\\"私有的缓存\\"，返回一个负责判断的函数。</li>\\n<li>现代 JS 还可以用 <code>static #instance</code> 私有字段、在构造函数里拦截 <code>new</code>，或者干脆利用 ES Module 只执行一次的特性。</li>\\n</ul>\\n</li>\\n<li><strong>前端里的典型应用</strong>：Vuex / Redux 的全局 Store、插件的 <code>install</code> 防重复安装、全局弹框、全局的请求实例 / 日志器 / 配置对象。</li>\\n<li><strong>Vuex 的做法</strong>：<code>install</code> 里用一个模块级变量记住已经装过的 <code>Vue</code>，同一个 <code>Vue</code> 再装一次就直接 <code>return</code>（开发环境顺便报错提示），保证一个应用只有一套 Store 注入逻辑。这道判断是 <code>Vue.use</code> 自带去重之外的第二层保险；两层都失效时，重复安装会让全局混入叠加、注入逻辑重复执行（常被简化成\\"Store 重新初始化、状态归零\\"的说法）。</li>\\n<li><strong>两道常考题</strong>：基于 <code>localStorage</code> 封装一个单例 <code>Storage</code>（静态方法版 + 闭包版都要会写）；实现一个全局唯一的 Modal 弹框（按需创建、反复复用同一个 DOM 节点）。</li>\\n<li><strong>要注意的坑</strong>：实例别挂在 <code>this</code> 上（那样每个对象各存一份，不是单例）；单例是全局可变状态，会给单元测试和 SSR 带来麻烦。</li>\\n</ul>"}');export{v as comp,m as data};
